package com.amit.jobagent.application;import com.amit.jobagent.common.api.PagedResponse;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/applications")class ApplicationTrackerController{private final ApplicationTrackerService s;ApplicationTrackerController(ApplicationTrackerService x){s=x;}@GetMapping PagedResponse<ApplicationTrackerResponse>list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="false")boolean archived){return s.list(page,size,archived);}@GetMapping("/{id}")ApplicationTrackerResponse get(@PathVariable UUID id){return s.get(id);}@PostMapping("/{id}/status")ApplicationTrackerResponse status(@PathVariable UUID id,@Valid@RequestBody TrackerStatusRequest r){return s.status(id,r);}@PostMapping("/{id}/notes")void note(@PathVariable UUID id,@Valid@RequestBody TrackerNoteRequest r){s.note(id,r);}@PostMapping("/{id}/archive")ApplicationTrackerResponse archive(@PathVariable UUID id){return s.archive(id);}@PostMapping("/{id}/restore")ApplicationTrackerResponse restore(@PathVariable UUID id){return s.restore(id);}@GetMapping("/{id}/timeline")List<ApplicationTimelineEvent>timeline(@PathVariable UUID id){return s.timeline(id);}}
